def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append((oid, opp))

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return max(0.0, min(budget, 35.0))
        return max(0.0, min(budget, 12.0))

    highest_prev = 0.0
    cindy_prev = None
    pressure_count = 0
    for oid, opp in alive_opponents:
        prev = opp.get('previous_trace', {}) or {}
        bid = prev.get('bid')
        if bid is not None:
            if bid > highest_prev:
                highest_prev = bid
            if bid >= 70.0:
                pressure_count += 1
        if oid == 'Cindy' and bid is not None:
            cindy_prev = bid

    scarcity = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))
    tight_supply = supply <= 17.0
    loose_supply = supply >= 22.0

    urgent = hp <= 2 or no_water_days >= 1
    semi_urgent = hp <= 4

    if cindy_prev is None:
        cindy_prev = 84.9

    target = 0.0

    if urgent:
        if tight_supply:
            target = max(88.0, cindy_prev + 1.0)
        else:
            target = max(80.0, cindy_prev - 2.0)
    elif semi_urgent:
        if tight_supply:
            target = max(82.0, cindy_prev - 1.0)
        elif loose_supply:
            target = 42.0
        else:
            target = 58.0
    else:
        if tight_supply:
            target = 76.0 if pressure_count == 0 else max(79.0, highest_prev - 3.0)
        elif loose_supply:
            target = 16.0
        else:
            target = 28.0 if pressure_count == 0 else 34.0

    if day >= 8:
        target += 6.0
    if hp >= 8 and not urgent and not tight_supply:
        target -= 4.0

    reserve_floor = 0.0
    if day < 9:
        reserve_floor = DAILY_SALARY * (10 - day) * 0.18
    spend_cap = max(0.0, budget - reserve_floor)
    if urgent:
        spend_cap = budget

    bid = min(target, spend_cap)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 7
    DAILY_SALARY = 80
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 20.0)
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if o.get('previous_trace') and o['previous_trace'].get('bid') is not None]
    avg_bid = sum(yesterday_bids) / len(yesterday_bids) if yesterday_bids else 40.0
    if my_status['hp'] <= 3:
        return min(my_status['budget'], DAILY_SALARY * 0.95)
    if yesterday_bids and max(yesterday_bids) > 85:
        return min(my_status['budget'], 86.0)
    return min(my_status['budget'], max(40.0, avg_bid + 2.0))
